from rdkit import Chem
import numpy as np
for f in ['nhc','p','benz']:
 m=Chem.MolFromMolFile(f+'.mol',removeHs=False); xyz=np.array(m.GetConformer().GetPositions());
 if f=='benz':
  a=xyz[1]-xyz[0];b=xyz[7]-xyz[0];print('benz angle',np.degrees(np.arccos(np.dot(a,b)/np.linalg.norm(a)/np.linalg.norm(b))))
 if f=='nhc':
  a=xyz[1]-xyz[0];b=xyz[13]-xyz[0];print('nhc angle',np.degrees(np.arccos(np.dot(a,b)/np.linalg.norm(a)/np.linalg.norm(b))))
